public function regenerate_all(): int {
    if ( ! function_exists( 'as_enqueue_async_action' ) ) { return 0; }

    $post_types = get_post_types( array( 'public' => true ), 'names' );
    $post_types = array_diff( $post_types, array( 'attachment' ) );

    $queued   = 0;
    $offset   = 0;
    $batch    = 200;

    do {
        $args = array(
            'post_type'      => $post_types,
            'post_status'    => 'publish',
            'posts_per_page' => $batch,
            'offset'         => $offset,
            'fields'         => 'ids',
            'orderby'        => 'ID',
            'order'          => 'ASC',
        );

        $post_ids = get_posts( $args );
        if ( empty( $post_ids ) ) { break; }

        foreach ( $post_ids as $post_id ) {
            as_enqueue_async_action(
                'wppo_used_css_generate',
                array( 'post_id' => $post_id ),
                'performance_optimisation'
            );
            ++$queued;
        }

        $offset += $batch;
    } while ( count( $post_ids ) === $batch );

    if ( $queued > 0 ) {
        Log::add( sprintf(
            __( 'Queued %d used-CSS regeneration jobs.', 'performance-optimisation' ),
            $queued
        ) );
    }

    return $queued;
}
